{
  "name": "持久化属性",
  "name_en": "Persistent Property",
  "manufacturer": "",
  "description": "用于实验软件中保存配置、元数据或对象状态的持久化属性组件。它可管理单个属性值，并在普通值、JSON 表示和字典存储格式之间转换，常用于实验记录、参数保存和对象状态持久化；不对应特定物理仪器。",
  "description_en": "A persistent property component used in laboratory software to store configuration, metadata, or object state. It manages a single property value and converts between native values, JSON representations, and dictionary-based storage formats. It is commonly used for experiment records, parameter saving, and state persistence, rather than representing a specific physical instrument.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭该持久化属性对象。",
      "description_en": "Close the persistent property object."
    },
    {
      "action_name": "auto-set_value",
      "description": "设置该持久化属性的值。",
      "description_en": "Set the value of the persistent property."
    },
    {
      "action_name": "auto-json_value",
      "description": "获取或设置该持久化属性的 JSON 表示。",
      "description_en": "Get or set the JSON representation of the persistent property."
    },
    {
      "action_name": "auto-read_from_dict",
      "description": "从字典数据中读取该持久化属性。",
      "description_en": "Read the persistent property from dictionary data."
    },
    {
      "action_name": "auto-write_to_dict",
      "description": "将该持久化属性写入字典数据。",
      "description_en": "Write the persistent property to dictionary data."
    },
    {
      "action_name": "auto-get_comparable_string",
      "description": "获取该持久化属性的可比较字符串表示。",
      "description_en": "Get a comparable string representation of the persistent property."
    },
    {
      "action_name": "auto-is_equal",
      "description": "判断该持久化属性是否与另一值相等。",
      "description_en": "Check whether the persistent property is equal to another value."
    }
  ],
  "tag_hints": [
    "data persistence",
    "metadata storage",
    "configuration saving",
    "JSON serialization",
    "dictionary read/write",
    "object state tracking"
  ]
}

